```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.List;

public class CommandExecutor {
    public void pingHost(String hostname) throws Exception {
        // To fix this, we pass the command and its arguments as a List/Array.
        // This ensures the operating system treats the input strictly as an argument 
        // to the 'ping' command rather than part of a shell command string.
        List<String> command = List.of("ping", "-c", "4", hostname);

        // ProcessBuilder handles the argument separation safely
        ProcessBuilder processBuilder = new ProcessBuilder(command);
        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
    }
}
```

